-- 1127: Blog post — "DP-300 Azure Database Administrator in Singapore: Exam Domains, Funding and Practice Exams"
--
--       Lead-in post for WSQ - Administering Microsoft Azure SQL Solutions (DP-300) (TGS-2024048319).
--       Backdated to 2025-09-30 (published, status 1). No LinkedIn / Facebook share is
--       performed: linkedin_urn carries the manual-skip sentinel and the post ships
--       already-published, so publishDue never picks it up.
--
-- Every figure below was read off the LIVE course page on 2026-08-26, not invented:
--   * Fee card: full $2,000.00, GST $180.00 (9%), baseline nett $1,180.00
--     (SG/PR 21+, 50%), MCES/SME nett $780.00 (SG 40+, 70%).
--   * Course information: 4 days / 32 hrs, Beginner, 2 hrs assessment.
--   * Funding validity 16 Aug 2024 - 15 Aug 2026; Absentee Payroll $4.50/hr.
--   * Skills Framework: Data Engineering (ICT-DIT-4005-1.1).
--   * Exam weightings from the official study guide, skills measured as of 24 Apr 2026.
--   * Practice-exam URL verified HTTP 200: https://exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-dp-300
--
-- Notes for future editors:
--  * apply.php splits statements on ";" at end-of-line — the content HTML below is ONE line.
--  * Idempotent: WHERE NOT EXISTS on url_key, INSERT IGNORE on tag links. Safe to re-run.
--  * SG-only guard via @mms_instance — the CTA course is SG WSQ, absent on MY/GH.
--  * hero_image_url is NOT set here (SQL cannot render one) — generate on prod post-deploy.

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);

INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `linkedin_urn`, `created_at`, `updated_at`) SELECT 'DP-300 Azure Database Administrator in Singapore: Exam Domains, Funding and Practice Exams', 'dp-300-azure-database-administrator-singapore-guide', 'DP-300 is the Microsoft credential for DBAs migrating and running SQL Server workloads on Azure. This guide walks the exam domains and their weightings, sets out exactly what you pay after WSQ funding &mdash; $1,180 nett, or $780 for Singapore Citizens aged 40 and above &mdash; and shows what the 4 days course covers.', '<div class="mmd-summary"><div class="mmd-summary-label">Summary</div><p><strong>DP-300</strong> is the Microsoft credential for DBAs migrating and running SQL Server workloads on Azure. This guide covers what the exam measures, what the 4 days WSQ course covers, and what you pay after SkillsFuture funding &mdash; <strong>$1,180</strong> for Singapore Citizens and PRs aged 21 and above, or <strong>$780</strong> for Singapore Citizens aged 40 and above.</p></div><h2>Why DP-300 is worth sitting</h2><p>Plenty of Singapore organisations still run SQL Server on-premise and are being asked when it moves to Azure. DP-300 is the certification for the people who have to answer that &mdash; covering migration strategy, the IaaS-versus-PaaS decision, security, performance tuning and high availability.</p><ul><li><strong>Migration is covered properly</strong>, including compatibility levels, Managed Instances and the Azure SQL migration extension.</li><li><strong>Security and high availability each carry 20&ndash;25%</strong>, reflecting what actually matters when a database is in production.</li><li><strong>Performance tuning gets a full 20&ndash;25%</strong> &mdash; the skill that most directly justifies a DBA salary.</li><li><strong>It is the natural credential for existing SQL Server DBAs</strong>, building on what you already know rather than starting over.</li></ul><p>The course is mapped to the Skills Framework under <strong>Data Engineering</strong> (TSC code ICT-DIT-4005-1.1), and leads to roles such as Azure Database Administrator, SQL Database Developer, Cloud Solutions Architect, Data Warehouse Architect. <a href="https://www.tertiarycourses.com.sg/wsq-administering-microsoft-azure-sql-solutions-dp-300.html">Check the funding you qualify for</a>.</p><h2>The DP-300 exam at a glance</h2><table><tbody><tr><td>Exam</td><td>DP-300: Administering Microsoft Azure SQL Solutions</td></tr><tr><td>Length</td><td>100 minutes</td></tr><tr><td>Passing score</td><td>700 out of 1000 (scaled &mdash; not 70%)</td></tr><tr><td>Certification</td><td>Azure Database Administrator Associate</td></tr><tr><td>Renewal</td><td>Free online renewal every 12 months</td></tr></tbody></table><h2>DP-300 exam domains and weightings</h2><p>These are the skills measured on the official study guide. The weightings tell you where to spend your revision time.</p><table><thead><tr><th>Skills measured</th><th>Weighting</th></tr></thead><tbody><tr><td>Plan and implement data platform resources</td><td>15&ndash;20%</td></tr><tr><td>Implement a secure environment</td><td>20&ndash;25%</td></tr><tr><td>Monitor, configure, and optimize database resources</td><td>20&ndash;25%</td></tr><tr><td>Configure and manage automation of tasks</td><td>15&ndash;20%</td></tr><tr><td>Plan and configure a high availability and disaster recovery environment</td><td>20&ndash;25%</td></tr></tbody></table><p><em>Source: official Microsoft study guide, skills measured as of 24 Apr 2026.</em></p><h2>What the WSQ course covers</h2><p>The 4 days (32 hrs) <a href="https://www.tertiarycourses.com.sg/wsq-administering-microsoft-azure-sql-solutions-dp-300.html"><strong>WSQ - Administering Microsoft Azure SQL Solutions (DP-300)</strong></a> course is pitched at <strong>Beginner</strong> level and is delivered in our Woodlands classroom with hands-on labs, followed by a 2 hrs assessment. The outline tracks the official objectives:</p><ol><li>Prepare to maintain SQL databases on Azure</li><li>Deploy IaaS solutions with Azure SQL</li><li>Deploy PaaS solutions with Azure SQL</li><li>Evaluate strategies for migrating to Azure SQL</li><li>Migrate SQL Server workloads to Azure SQL Database</li><li>Migrate SQL workloads to Azure Managed Instances</li><li>Configure database authentication and authorization</li><li>Protect data in-transit and at rest</li><li>Implement compliance controls for sensitive data</li><li>Describe performance monitoring</li><li>Configure SQL Server resources for optimal performance</li><li>Configure databases for optimal performance</li><li>Explore query performance optimization</li><li>Explore performance-based design</li></ol><p>The full outline runs to 21 topics &mdash; see the <a href="https://www.tertiarycourses.com.sg/wsq-administering-microsoft-azure-sql-solutions-dp-300.html">course page</a> for the complete list.</p><h2>Practise before you book the exam</h2><p>Course participants get free, unlimited access to our <a href="https://exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-dp-300">DP-300 practice exams</a> on the Tertiary Infotech Practice Exam Portal, in both Practice Mode (with instant explanations) and timed Exam Mode. The portal offers non-participants 10 free questions per exam.</p><h2>What you actually pay: funding for DP-300 training</h2><p>The full fee is $2,000 before GST. As an SWDA-funded WSQ course, the subsidy depends on your citizenship, age and who is sponsoring you:</p><table><thead><tr><th>Who you are</th><th>Subsidy</th><th>You pay (incl. GST)</th></tr></thead><tbody><tr><td>Non-funded / international participants</td><td>&ndash;</td><td>$2,180</td></tr><tr><td>Singapore Citizen or PR, aged 21 and above</td><td>50%</td><td><strong>$1,180</strong></td></tr><tr><td>Singapore Citizen aged 40 and above (MCES), or SME-sponsored</td><td>70%</td><td><strong>$780</strong></td></tr></tbody></table><p><em>GST of $180 is charged at 9% on the full course fee of $2,000, as required for SWDA-funded courses &mdash; the subsidy applies to the course fee, not the tax.</em></p><p>Funding for this course is valid from <strong>16 Aug 2024</strong> to <strong>15 Aug 2026</strong>. You must register and complete the course within that window to qualify.</p><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">1. SkillsFuture Credit (SFC)</summary><div class="mmd-faq-a"><p>Singaporeans aged 25 and above have an opening SkillsFuture Credit of $500 plus any top-ups, and those aged 40 and above received a $4,000 Mid-Career top-up. Credit can offset the fee payable after subsidy, though the Mid-Career top-up cannot be used on this course. <a href="https://www.tertiarycourses.com.sg/how-to-claim-skillsfuture-credit.html">How to claim SkillsFuture Credit</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">2. SkillsFuture Enterprise Credit (SFEC)</summary><div class="mmd-faq-a"><p>Eligible employers can draw on SFEC to cover out-of-pocket costs when sponsoring staff. See our <a href="https://www.tertiarycourses.com.sg/sfec.html">SFEC guide</a> for who qualifies and how to claim.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">3. PSEA</summary><div class="mmd-faq-a"><p>Singapore Citizens can use Post-Secondary Education Account funds to offset the fee payable after subsidy. This course carries the PSEA tag, so it is eligible.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">4. UTAP</summary><div class="mmd-faq-a"><p>NTUC members can claim 50% of the unfunded fee under UTAP, capped at $250 a year, or $500 a year for members aged 40 and above. See the <a href="https://www.tertiarycourses.com.sg/utap.html">UTAP guide</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">5. Absentee Payroll</summary><div class="mmd-faq-a"><p>Employers sponsoring staff can claim Absentee Payroll at $4.50 an hour, capped at $100,000 per enterprise per year, for the hours staff spend in training.</p></div></details></div><p><a href="https://www.tertiarycourses.com.sg/wsq-administering-microsoft-azure-sql-solutions-dp-300.html"><strong>See the live fee breakdown for your profile &rarr;</strong></a></p><h2>Your route to certification</h2><ol><li><strong>Register for the 4 days WSQ course.</strong> Pick an intake on the <a href="https://www.tertiarycourses.com.sg/wsq-administering-microsoft-azure-sql-solutions-dp-300.html">course page</a> and apply your funding at checkout.</li><li><strong>Attend and complete the assessment.</strong> You need at least 75% attendance and a pass in the 2 hrs assessment to receive your WSQ Statement of Attainment.</li><li><strong>Rehearse on the practice exams</strong> until you are consistently clearing the pass mark under timed conditions.</li><li><strong>Book and sit DP-300</strong> through Pearson VUE. The certification exam is booked and paid for separately from the course.</li></ol><h2>Where to go after DP-300</h2><p>For the broader architecture picture, AZ-305 covers designing Azure infrastructure solutions. If your work is shifting towards analytics, <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-fabric-data-engineer-associate-dp-700-training.html">DP-700 on Microsoft Fabric</a> is the current data-engineering track. Browse the full <a href="https://www.tertiarycourses.com.sg/microsoft-certifications-exams.html">Microsoft certification course catalogue</a> to plan the next rung.</p><h2>Frequently asked questions</h2><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">Do I need SQL Server experience?</summary><div class="mmd-faq-a"><p>Yes, in practice. The course covers migrating and administering SQL workloads on Azure and assumes you already understand relational database administration.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Does this cover both Azure SQL Database and SQL Server on VMs?</summary><div class="mmd-faq-a"><p>Yes. Both IaaS deployments (SQL Server on Azure VMs) and PaaS options (Azure SQL Database, Managed Instance) are covered, including how to choose between them.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Is the exam fee included?</summary><div class="mmd-faq-a"><p>No. The course fee covers training and the WSQ assessment. The DP-300 exam is booked separately through Pearson VUE.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">How long is the course?</summary><div class="mmd-faq-a"><p>4 days (32 hours), followed by a 2-hour assessment.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Does the certification expire?</summary><div class="mmd-faq-a"><p>Yes, annually, with free online renewal through Microsoft Learn.</p></div></details></div><h2>Register for Azure Database Administrator training</h2><p>Seats are limited and classes fill ahead of each intake. View upcoming dates and reserve your place on the <a href="https://www.tertiarycourses.com.sg/wsq-administering-microsoft-azure-sql-solutions-dp-300.html"><strong>WSQ - Administering Microsoft Azure SQL Solutions (DP-300)</strong></a> course page, or call us on +65 6100 0613 if you would like your funding worked out first.</p>', 'Tertiary Infotech Academy', 1, '2025-09-30', 'TGS-2024048319', 'TGS-2024048319', 'DP-300 Course Singapore | Azure Database Administrator | WSQ Funding', 'Train for DP-300 Azure Database Administrator in Singapore. 4 days WSQ course from $780 nett after funding, full exam domain breakdown, and free practice exams for participants.', 'dp-300 course singapore, azure database administrator certification, dp-300 exam, wsq microsoft course, skillsfuture microsoft certification, microsoft certification singapore, dp-300 funding, dp-300 training singapore', 'manual-skip-no-share', '2025-09-30 09:00:00', '2025-09-30 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'dp-300-azure-database-administrator-singapore-guide');

